function input({ body }) {
  const m = body?.message,
    id = m?.chat?.id,
    reply = m?.message_id;
  if (!Number.isSafeInteger(id) || id === 0 || !Number.isSafeInteger(reply) || reply <= 0)
    throw Error("Invalid Telegram message");
  const address = typeof m.text === "string" ? m.text : "";
  return {
    chatId: String(id),
    replyToMessageId: reply,
    address,
    looksValid: /^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(address),
    request: { address, visible: true },
    text: "Please enter a complete valid TRON address.",
  };
}

return [{ json: input({ body: { message: $input.first().json.message } }) }];

function validate({ body, address }) {
  if (!body || typeof body !== "object" || typeof body.result !== "boolean")
    throw Error("TRON address validation unavailable");
  if (!body.result)
    return { valid: false, request: {}, text: "Please enter a complete valid TRON address." };
  const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
  let n = 0n;
  for (const c of address) {
    const v = alphabet.indexOf(c);
    if (v < 0) throw Error("Invalid address");
    n = n * 58n + BigInt(v);
  }
  const hex = n.toString(16).padStart(50, "0");
  if (hex.length !== 50 || !hex.startsWith("41")) throw Error("Invalid TRON address bytes");
  const parameter = hex.slice(2, 42).padStart(64, "0"),
    contract = "TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t";
  return {
    valid: true,
    request: {
      owner_address: contract,
      contract_address: contract,
      function_selector: "getBlackListStatus(address)",
      parameter,
      visible: true,
    },
    text: "Please enter a complete valid TRON address.",
  };
}

const original = $("Read the TRON address").first().json;
return [
  {
    json: {
      ...validate({ body: $input.first().json, address: original.address }),
      chatId: original.chatId,
      replyToMessageId: original.replyToMessageId,
    },
  },
];

function result({ body, address }) {
  if (
    !body ||
    body.result?.result !== true ||
    !Array.isArray(body.constant_result) ||
    body.constant_result.length !== 1 ||
    typeof body.constant_result[0] !== "string" ||
    !/^0{63}[01]$/.test(body.constant_result[0])
  )
    throw Error("USDT contract result unavailable");
  const blacklisted = body.constant_result[0].endsWith("1");
  return {
    text: blacklisted
      ? `TRON USDT contract reports ${address} is blacklisted.`
      : `TRON USDT contract reports ${address} is not blacklisted.`,
  };
}

const original = $("Read the TRON address").first().json;
return [
  {
    json: {
      ...result({ body: $input.first().json, address: original.address }),
      chatId: original.chatId,
      replyToMessageId: original.replyToMessageId,
    },
  },
];
